<script setup lang="ts">
definePageMeta({layout:'admin'});useSeoMeta({title:'网站设置'});const session=useState<{csrfToken:string}|null>('admin-session');const {data:response}=await useFetch<any>('/api/admin/settings');const form=reactive(response.value.data);form.techStackText=form.techStack.join(', ');const pending=ref(false);const message=ref('')
async function save(){if(!session.value)return;pending.value=true;message.value='';try{const {techStackText,...body}=form;body.techStack=techStackText.split(/[,，]/).map((x:string)=>x.trim()).filter(Boolean);await $fetch('/api/admin/settings',{method:'PUT',body,headers:{'X-CSRF-Token':session.value.csrfToken}});message.value='设置已保存'}catch(e:any){message.value=e?.data?.error?.message||'保存失败'}finally{pending.value=false}}
</script>
<template><section class="settings"><header><p class="eyebrow">SYSTEM</p><h1>网站设置</h1></header><form @submit.prevent="save"><UCard><template #header><strong>基础信息</strong></template><div class="fields"><UFormField label="网站名称"><UInput v-model="form.siteName"/></UFormField><UFormField label="个人名称"><UInput v-model="form.personName"/></UFormField><UFormField label="网站描述"><UTextarea v-model="form.siteDescription"/></UFormField><UFormField label="个人简介"><UTextarea v-model="form.bio"/></UFormField><UFormField label="当前状态"><UInput v-model="form.currentStatus"/></UFormField><UFormField label="Email"><UInput v-model="form.email"/></UFormField><UFormField label="头像 URL"><UInput v-model="form.avatarUrl"/></UFormField><UFormField label="Logo URL"><UInput v-model="form.logoUrl"/></UFormField></div></UCard><UCard><template #header><strong>首页与关于页</strong></template><div class="stack"><UFormField label="技术栈（逗号分隔）"><UInput v-model="form.techStackText"/></UFormField><UFormField label="首页精选项目数量"><UInput v-model.number="form.featuredProjectCount" type="number"/></UFormField><UFormField label="关于页 Markdown"><UTextarea v-model="form.aboutMarkdown" :rows="16"/></UFormField></div></UCard><UCard><template #header><strong>社交与 SEO</strong></template><div class="fields"><UFormField v-for="key in Object.keys(form.social)" :key="key" :label="key"><UInput v-model="form.social[key]"/></UFormField><UFormField label="默认 SEO 标题"><UInput v-model="form.seo.title"/></UFormField><UFormField label="默认 SEO 描述"><UTextarea v-model="form.seo.description"/></UFormField><UFormField label="默认 OG 图片"><UInput v-model="form.seo.ogImage"/></UFormField></div></UCard><div class="save"><span>{{message}}</span><UButton type="submit" :loading="pending">保存网站设置</UButton></div></form></section></template>
<style scoped>.settings,.settings form{display:grid;gap:22px}.settings h1{margin:0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.stack{display:grid;gap:16px}.save{position:sticky;bottom:16px;display:flex;justify-content:flex-end;align-items:center;gap:16px;padding:12px;border:1px solid var(--color-border);border-radius:8px;background:var(--color-background)}@media(max-width:700px){.fields{grid-template-columns:1fr}}</style>
